from scipy.stats import mode

def task_func(list_of_lists):
    if list_of_lists is None:
        return np.array([]), 0

    merged_list = []
    for sublist in list_of_lists:
        if sublist is None:
            continue
        if np.isscalar(sublist):
            merged_list.append(sublist)
        else:
            merged_list.extend(sublist)

    merged_array = np.asarray(merged_list)

    if merged_array.size == 0:
        return np.array([]), 0

    mode_result = mode(merged_array, axis=None, keepdims=True)
    mode_value = np.atleast_1d(np.asarray(mode_result.mode))
    mode_count = int(np.asarray(mode_result.count).reshape(-1)[0])

    return mode_value, mode_count
