import os
import csv
from openpyxl import load_workbook


def task_func(file_name, excel_file_path, csv_file_path) -> str:
    """
    Convert the active sheet of an Excel file to CSV.

    The output path may be provided directly via `csv_file_path`. If that path
    looks like a directory (existing directory or trailing separator), the CSV
    file name is derived from `file_name` when provided, otherwise from the
    source Excel file name.
    """

    def _base_name() -> str:
        candidate = file_name if isinstance(file_name, str) and file_name.strip() else excel_file_path
        return os.path.splitext(os.path.basename(candidate))[0] or "output"

    def _resolve_output_path() -> str:
        target = csv_file_path or ""
        if target and (
            target.endswith(os.sep)
            or (os.altsep is not None and target.endswith(os.altsep))
            or os.path.isdir(target)
        ):
            return os.path.join(target, _base_name() + ".csv")

        if not target:
            return os.path.join(os.path.dirname(excel_file_path) or ".", _base_name() + ".csv")

        root, ext = os.path.splitext(target)
        if not ext:
            return target + ".csv"
        return target

    output_path = _resolve_output_path()
    os.makedirs(os.path.dirname(output_path) or ".", exist_ok=True)

    workbook = None
    try:
        try:
            workbook = load_workbook(excel_file_path, data_only=True)
            sheet = workbook.active

            with open(output_path, "w", newline="", encoding="utf-8") as csv_file:
                writer = csv.writer(csv_file)
                for row in sheet.iter_rows(values_only=True):
                    writer.writerow(["" if cell is None else cell for cell in row])

        except Exception as openpyxl_error:
            # Optional fallback for legacy .xls files if pandas/xlrd are available.
            try:
                import pandas as pd  # type: ignore

                df = pd.read_excel(excel_file_path, sheet_name=0, header=None)
                df.to_csv(output_path, index=False, header=False, encoding="utf-8")
            except Exception:
                raise openpyxl_error

    finally:
        if workbook is not None:
            workbook.close()

    return os.path.basename(output_path)
