import subprocess
import os
import shutil
from glob import glob


def task_func(src_folder, dst_folder):
    """
    Compress every file in src_folder with gzip and move the compressed
    files into dst_folder.

    Returns:
        dict: {
            'success': bool,
            'message': str,
            'failed_files': list[str]
        }
    """
    failed_files = []

    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": f"Source folder does not exist or is not a directory: {src_folder}",
            "failed_files": [],
        }

    patterns = (os.path.join(src_folder, "*"), os.path.join(src_folder, ".*"))
    source_files = sorted(
        {
            path
            for pattern in patterns
            for path in glob(pattern)
            if os.path.isfile(path)
        }
    )

    if not source_files:
        return {
            "success": True,
            "message": "No files found to compress.",
            "failed_files": [],
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except Exception as exc:
        return {
            "success": False,
            "message": f"Failed to create or access destination folder: {exc}",
            "failed_files": [os.path.basename(path) for path in source_files],
        }

    for src_path in source_files:
        filename = os.path.basename(src_path)
        temp_output = os.path.join(src_folder, f".{filename}.gz.tmp")
        final_output = os.path.join(dst_folder, f"{filename}.gz")

        try:
            if os.path.exists(temp_output):
                os.remove(temp_output)

            with open(temp_output, "wb") as out_handle:
                proc = subprocess.Popen(
                    ["gzip", "-c", src_path],
                    stdout=out_handle,
                    stderr=subprocess.PIPE,
                )
                _, stderr = proc.communicate()

            if proc.returncode != 0:
                raise subprocess.CalledProcessError(
                    proc.returncode,
                    ["gzip", "-c", src_path],
                    output=None,
                    stderr=stderr,
                )

            if os.path.exists(final_output):
                os.remove(final_output)

            shutil.move(temp_output, final_output)

        except Exception:
            failed_files.append(filename)

            try:
                if os.path.exists(temp_output):
                    os.remove(temp_output)
            except Exception:
                pass

            try:
                if os.path.exists(final_output):
                    os.remove(final_output)
            except Exception:
                pass

    success = len(failed_files) == 0
    if success:
        message = "Successfully compressed and moved all files."
    else:
        message = f"Completed with {len(failed_files)} failed file(s)."

    return {
        "success": success,
        "message": message,
        "failed_files": failed_files,
    }
