def task_func(input_string):
    """
    Split a multi-line string into lines, tokenize into words, remove stopwords,
    and return a dictionary of word frequencies.
    """
    if input_string is None:
        return {}

    if not isinstance(input_string, str):
        input_string = str(input_string)

    words = []
    for line in input_string.splitlines():
        tokens = re.findall(r"[A-Za-z]+(?:'[A-Za-z]+)?", line.lower())
        words.extend(token for token in tokens if token not in STOPWORDS)

    return dict(Counter(words))
