import math
import statistics
import numpy as np


def _round_nearest_int(value):
    """Round to the nearest integer, with halves rounded away from zero."""
    if value >= 0:
        return int(math.floor(value + 0.5))
    return int(math.ceil(value - 0.5))


def _stable_mode(values):
    """Return a deterministic mode value from a non-empty sequence."""
    modes = statistics.multimode(values)
    return min(modes) if modes else 0


def task_func(input_list):
    try:
        values = [float(x) for x in input_list]
    except Exception as exc:
        raise TypeError("input_list must contain only numeric values") from exc

    if not values:
        return (0, 0, 0, 0, 0, 0)

    if any(not math.isfinite(x) for x in values):
        raise ValueError("input_list must contain only finite numeric values")

    sorted_values = sorted(values)

    mean_sorted = _round_nearest_int(statistics.mean(sorted_values))
    median_sorted = _round_nearest_int(statistics.median(sorted_values))
    mode_sorted = _round_nearest_int(_stable_mode(sorted_values))

    fft_magnitudes = np.abs(np.fft.fft(np.asarray(values, dtype=float)))
    fft_magnitudes_rounded = [_round_nearest_int(x) for x in fft_magnitudes]

    mean_fft = _round_nearest_int(statistics.mean(fft_magnitudes_rounded))
    median_fft = _round_nearest_int(statistics.median(fft_magnitudes_rounded))
    mode_fft = _round_nearest_int(_stable_mode(fft_magnitudes_rounded))

    return (mean_sorted, median_sorted, mode_sorted, mean_fft, median_fft, mode_fft)
