        }

    if shutil.which("gzip") is None:
        return {
            "success": False,
            "message": "gzip command not found; no files were compressed.",
            "failed_files": [os.path.basename(p) for p in src_paths],
        }

    succeeded = 0

    for src_path in src_paths:
        filename = os.path.basename(src_path)
        final_path = os.path.join(dst_folder, filename + ".gz")
        temp_path = os.path.join(dst_folder, f".{filename}.gz.{os.getpid()}.tmp")

        try:
            if os.path.exists(temp_path):
                os.remove(temp_path)

            with open(temp_path, "wb") as out_file:
                proc = subprocess.Popen(
                    ["gzip", "-c", src_path],
                    stdout=out_file,
                    stderr=subprocess.PIPE,
                )
                _, stderr = proc.communicate()

            if proc.returncode != 0:
                err_text = stderr.decode("utf-8", errors="replace").strip()
                raise RuntimeError(err_text or f"gzip failed for {filename}")

            os.replace(temp_path, final_path)
            succeeded += 1

        except Exception:
            failed_files.append(filename)
            try:
                if os.path.exists(temp_path):
                    os.remove(temp_path)
            except OSError:
                pass

    success = len(failed_files) == 0
    if success:
        message = f"Compressed and moved {succeeded} file(s) successfully."
    else:
        message = (
            f"Compressed and moved {succeeded} of {total_files} file(s) successfully; "
            f"{len(failed_files)} file(s) failed."
        )

    return {
        "success": success,
        "message": message,
        "failed_files": failed_files,
    }
